mapper.select:
SELECT *
FROM (
    SELECT
        BATCH_NO AS batchNo,
        PRODUCT_NO AS productNo,
        CATEGORY_NO AS categoryNo,
        PRODUCT_NAME AS productName,
        ORIGIN AS origin,
        PURCHASE_UNIT AS purchaseUnit,
        PURCHASE_QTY AS purchaseQty,
        PURCHASE_PRICE AS purchasePrice,
        PURCHASE_DATE AS purchaseDate,
        SUPPLIER_NAME AS supplierName,
        STATUS AS status,
        CREATED_AT AS createdAt
    FROM OFT_PURCHASE_BATCH
    WHERE PRODUCT_NAME = #{productName}
      AND CATEGORY_NO = #{categoryNo}
      AND PRODUCT_NO = #{productNo}
      AND NVL(ORIGIN, ' ') = NVL(#{origin}, ' ')
      AND PURCHASE_UNIT = #{purchaseUnit}
      AND PURCHASE_QTY = #{purchaseQty}
      AND PURCHASE_PRICE = #{purchasePrice}
      AND PURCHASE_DATE = #{purchaseDate}
      AND NVL(SUPPLIER_NAME, ' ') = NVL(#{supplierName}, ' ')
      AND STATUS = #{status}
    ORDER BY BATCH_NO DESC
)
WHERE ROWNUM = 1

mapper.update:
UPDATE OFT_PURCHASE_BATCH
SET PRODUCT_NO = #{productNo}
WHERE BATCH_NO = #{batchNo}

UPDATE OFT_PURCHASE_BATCH
SET STATUS = #{status}
WHERE BATCH_NO = #{batchNo}

UPDATE OFT_PRODUCT
SET STOCK_QTY = STOCK_QTY + #{quantity}
WHERE PRODUCT_NO = #{productNo}
